function lang(){
  const q=new URLSearchParams(location.search).get('lang');
  const h=(document.documentElement.lang||'').split('-')[0].toLowerCase();
  const l=(q||h||'en').toLowerCase();
  return LANGS.includes(l)?l:'en';
}
function canonical(s){if(DATA[s])return s;for(const [en,a] of Object.entries(DATA))if(a.includes(s))return en;return s;}
function tr(s,l){
  const en=canonical(s);if(l==='en')return en;
  const a=DATA[en]; if(!a) return s;
  return a[LANGS.indexOf(l)-1]||en;
}
function localize(root,l){
  const w=document.createTreeWalker(root||document.body,NodeFilter.SHOW_TEXT);
  const nodes=[]; while(w.nextNode()) nodes.push(w.currentNode);
  for(const n of nodes){
    const raw=n.nodeValue, t=raw.trim(); if(!t) continue;
    const z=tr(t,l); if(z!==t) n.nodeValue=raw.replace(t,z);
  }
  for(const el of (root||document).querySelectorAll?.('input[placeholder],textarea[placeholder]')||[]){
    const p=el.getAttribute('placeholder')||'',z=tr(p,l); if(z!==p)el.setAttribute('placeholder',z);
  }
}
function chooseUse(kind){
  const sel=document.getElementById('useType'); if(!sel)return;
  const pats={office:['office'],school:['school','classroom'],warehouse:['warehouse','logistics']};
  const pp=pats[kind]||[];
  const opts=[...sel.options]; let o=opts.find(x=>pp.includes(String(x.value).toLowerCase()));
  if(!o)o=opts.find(x=>pp.some(p=>String(x.textContent).toLowerCase().includes(p)));
  if(o)sel.value=o.value;
}
