 office:{floorArea:1200,storeys:2,height:3,aspect:1.5,glazingFraction:.30,envelopePreset:'earlyInsulated',glazingPreset:'oldDouble',indoorC:21,outdoorC:-8,dynRam:.07,dynCair:70,dynCmass:1600,dynInitialAir:21,dynInitialMass:21,dynComfortMin:20,dynComfortMax:23},
